{
  "name": "@agent-context/opencode-sift",
  "version": "0.0.7",
  "description": "OpenCode plugin that compresses tool results with @agent-context/sift",
  "license": "Apache-2.0",
  "type": "module",
  "main": "./index.ts",
  "exports": {
    ".": "./index.ts",
    "./server": "./index.ts",
    "./tui": "./tui.tsx"
  },
  "files": [
    "index.ts",
    "tui.tsx",
    "lib",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "sift",
    "context-compression"
  ],
  "scripts": {
    "test": "node --test --experimental-strip-types test/*.test.ts"
  },
  "dependencies": {
    "@agent-context/sift": "0.0.1",
    "@opencode-ai/plugin": "1.18.26",
    "@opentui/core": "0.4.5",
    "@opentui/solid": "0.4.5",
    "solid-js": "1.9.12"
  },
  "devDependencies": {
    "@types/node": "^22.15.0"
  },
  "engines": {
    "opencode": ">=1.18.26 <2"
  }
}
